153	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
154	async function scheduleNode(planRamMB: number) {
155	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
156	  if (nodes.length === 0) return null;
157	  const loads = await Promise.all(
158	    nodes.map(async (n) => {
159	      const agg = await db.server.findMany({
160	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
161	        select: { plan: { select: { ramMB: true } } },
162	      });
163	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
164	      return { node: n, free: n.capacityRamMB - used };
165	    }),
166	  );
167	  loads.sort((a, b) => b.free - a.free);
168	  return loads[0].node;
169	}
