271	/**
272	 * True when this session's card payment is the FUNDING LEG of a purchase — a VPS
273	 * order, an upgrade, a disk expansion — rather than a wallet top-up the customer
274	 * bought for its own sake.
275	 *
276	 * The wallet is the settlement bus for every card-paid purchase: the card amount
277	 * is credited in, then the purchase debits the full total back out. That credit is
278	 * plumbing, not a product, and it must not be documented as one.
279	 *
280	 * REAL INCIDENT (2026-07-26 rehearsal, H3): every paid session got a PAID "Wallet
281	 * top-up" invoice here AND a PAID invoice from whatever it funded, so one $82.53
282	 * annual purchase produced `Wallet top-up $82.53` + `Starter VPS — Annual $82.53`
283	 * and the invoices page reported $165.06 paid lifetime — a customer reconciling
284	 * against their card statement saw twice their spend. Each document was internally
285	 * consistent; there were simply two of them for one payment. worker/billing.ts
286	 * already states the rule for the renewal path: "No invoice for the card leg …
287	 * a second document for the card portion would double-count the same revenue."
288	 *
289	 * Reads the same three metadata keys `lib/fulfil-checkout.ts` dispatches on, so
290	 * "did this session fund a purchase" has one answer, not two.
291	 */
292	export function isPurchaseLegSession(metadata: Stripe.Metadata | null | undefined): boolean {
293	  return !!(metadata?.nxeonOrder || metadata?.nxeonResize || metadata?.nxeonDiskExpand);
294	}
