296	/**
297	 * Credit a user's wallet for a completed Checkout session, idempotently.
298	 * Called from both the success-redirect confirm route (works without HTTPS)
299	 * and the webhook (belt-and-suspenders once HTTPS is available).
300	 * Returns true if a credit was applied this call.
301	 */
302	export async function creditCheckoutSession(sessionId: string): Promise<boolean> {
303	  const session = await stripe().checkout.sessions.retrieve(sessionId);
304	  const userId = session.metadata?.nxeonUserId;
305	  const cents = session.amount_total ?? 0;
306	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
307	
308	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
309	  // session id inside the description.
310	  const legacy = await db.walletTransaction.findFirst({
311	    where: { stripeSessionId: null, description: { contains: session.id } },
312	  });
313	  if (legacy) return false;
314

314	
