31	export type FulfilResult = {
32	  /** Where the browser should end up. The webhook ignores this. */
33	  redirect: string;
34	  /** True when THIS call performed the fulfilment work. */
35	  fulfilled: boolean;
36	  kind: "order" | "resize" | "diskExpand" | "topup" | "none";
