67	  // transaction). We deliberately IGNORE its return value now — it reports who
68	  // won the credit race, which is not the same question as "has this been
69	  // fulfilled", and conflating the two was the bug.
70	  await creditCheckoutSession(sessionId).catch(() => false);
71	
72	  const order = await getCheckoutOrderIntent(sessionId);
73	  if (order) {
74	    if (!(await claim(sessionId, "order"))) {
75	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
76	    }
77	    try {
78	      const user = await db.user.findUnique({ where: { id: order.userId } });
79	      if (!user) throw new Error("user not found for paid order");
80	      // Settle the price stamped on the session BEFORE the card was charged — never
81	      // a fresh quote taken now. The customer has already paid the card leg of that
82	      // exact total; re-pricing here and taking the difference out of the wallet is
83	      // the H2 incident (see OrderPrice in lib/order.ts). This is the same shape as
84	      // the resize and disk-expand branches below, which have always passed the
85	      // amount through metadata for this reason.
86	      const serverId = await placeOrder(user, order.intent, order.sold);
87	      await settle(sessionId, "DONE", serverId);
