104	      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "order", error: msg };
105	    }
106	  }
107	
108	  const resize = await getCheckoutResizeIntent(sessionId);
109	  if (resize) {
110	    const back = `${base}/dashboard/servers/${resize.serverId}`;
111	    if (!(await claim(sessionId, "resize"))) {
112	      return { redirect: back, fulfilled: false, kind: "resize" };
113	    }
114	    try {
115	      await applyResize({
116	        serverId: resize.serverId,
117	        planId: resize.planId,
118	        actorUserId: resize.userId,
119	        chargeCents: resize.chargeCents,
120	      });
121	      await settle(sessionId, "DONE", resize.serverId);
122	      return { redirect: back, fulfilled: true, kind: "resize" };
123	    } catch (e) {
124	      const msg = String((e as Error)?.message ?? e);
125	      await settle(sessionId, "FAILED", msg);
126	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "resize", error: msg };
127	    }
128	  }
129	
130	  const expand = await getCheckoutDiskExpandIntent(sessionId);
131	  if (expand) {
132	    const back = `${base}/dashboard/servers/${expand.serverId}`;
133	    if (!(await claim(sessionId, "diskExpand"))) {
134	      return { redirect: `${back}?tab=resize`, fulfilled: false, kind: "diskExpand" };
135	    }
136	    try {
137	      await applyDiskExpand({
138	        serverId: expand.serverId,
139	        addGB: expand.addGB,
140	        actorUserId: expand.userId,
141	        chargeCents: expand.chargeCents,
142	      });
143	      await settle(sessionId, "DONE", expand.serverId);
144	      return { redirect: `${back}?tab=resize`, fulfilled: true, kind: "diskExpand" };
145	    } catch (e) {
146	      const msg = String((e as Error)?.message ?? e);
147	      await settle(sessionId, "FAILED", msg);
148	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "diskExpand", error: msg };
149	    }
150	  }
151	
152	  // Plain wallet top-up: crediting above is the whole job.
153	  return { redirect: `${base}/dashboard/billing?paid=1`, fulfilled: true, kind: "topup" };
