 * Reload nginx, and confirm it is actually running afterwards.
 *
 * `nginx -t` was already checked; the RELOAD's exit code was discarded (M7 #4),
 * so a reload that failed — or a restart that left the daemon dead — read as a
 * successful configuration change. A dead nginx takes down every OTHER site on
 * the box too, which is why this is checked rather than hoped for.
 */
export async function reloadNginx(conn: import("ssh2").Client): Promise<void> {
  const test = await exec(conn, "nginx -t", SETUP_TIMEOUT_MS);
  if (test.code !== 0) throw new Error(`nginx config test failed: ${(test.stderr || test.stdout).trim().slice(0, 200)}`);
  const r = await exec(conn, "systemctl reload nginx || systemctl restart nginx", SETUP_TIMEOUT_MS);
  const active = await exec(conn, "systemctl is-active nginx 2>/dev/null", QUICK_TIMEOUT_MS);
  const state = active.stdout.trim();
  if (state !== "active") {
    throw new Error(
      `nginx is "${state || "not running"}" after the reload (systemctl exited ${r.code}), so no site on this ` +
        `server is being served. Diagnose with: systemctl status nginx ; journalctl -u nginx -n 50`
    );
  }
}

